94	+import { describe, expect, it } from "vitest";
95	+import { ENGAGEMENT_RANGE_TILES, SIGHT_RADIUS_TILES, WORLD_STEPS_PER_SECOND } from "../sailing.js";
96	+import { encounterRules, secondsToTicks, validateEncounterRules } from "./index.js";
97	+
98	+function issuesOf(candidate: unknown): string[] {
99	+  const result = validateEncounterRules(candidate);
100	+  return result.ok ? [] : result.issues;
101	+}
102	+
103	+describe("encounter rules (§2, §6, §14)", () => {
104	+  it("hold §6's timings in world ticks and the decided ranges and cones", () => {
105	+    expect(WORLD_STEPS_PER_SECOND).toBe(20);
106	+    expect(secondsToTicks(0.6)).toBe(12);
107	+    expect(encounterRules.grapple).toEqual({ windupTicks: 20, rangeTiles: ENGAGEMENT_RANGE_TILES, hitConeHeadings: 4, targetConeHeadings: 8, missCooldownTicks: 120 });
108	+    expect(encounterRules.challenge).toEqual({ windupTicks: 12, rangeTiles: 2, hitConeHeadings: 4, targetConeHeadings: 8, missCooldownTicks: 120 });
109	+    expect(encounterRules).toMatchObject({
110	+      maxDuels: 4,
111	+      transitionTicks: 60,
112	+      readyTimeoutTicks: 200,
113	+      spawnProtectionTicks: 900,
114	+      winProtectionTicks: 160,
115	+      drawProtectionTicks: 160,
116	+      respawnDelayTicks: 300,
117	+      respawnProtectionTicks: 400,
118	+      respawnClearRadiusTiles: SIGHT_RADIUS_TILES,
119	+      drawReturnMinSeparationTiles: 3,
120	+      drawReturnMaxDistanceTiles: 6,
121	+    });
122	+    expect(validateEncounterRules(encounterRules)).toEqual({ ok: true, value: encounterRules });
123	+  });
124	+
125	+  it("refuse a negative duration", () => {
126	+    expect(issuesOf({ ...encounterRules, respawnDelayTicks: -1 })[0]).toMatch(/^respawnDelayTicks:/);
127	+    expect(issuesOf({ ...encounterRules, grapple: { ...encounterRules.grapple, missCooldownTicks: -120 } })[0]).toMatch(/^grapple\.missCooldownTicks:/);
128	+    expect(issuesOf({ ...encounterRules, challenge: { ...encounterRules.challenge, windupTicks: -12 } })[0]).toMatch(/^challenge\.windupTicks:/);
129	+  });
130	+
131	+  it("refuse a range above the sight radius, but allow one exactly at it", () => {
132	+    const beyond = { ...encounterRules, grapple: { ...encounterRules.grapple, rangeTiles: SIGHT_RADIUS_TILES + 1 } };
133	+    expect(issuesOf(beyond)[0]).toMatch(/^grapple\.rangeTiles:/);
134	+    expect(issuesOf({ ...encounterRules, challenge: { ...encounterRules.challenge, rangeTiles: SIGHT_RADIUS_TILES } })).toEqual([]);
135	+  });
136	+
137	+  it("refuse a zero windup, fractional ticks, cones past a half turn, bad return geometry and unknown fields", () => {
138	+    expect(issuesOf({ ...encounterRules, grapple: { ...encounterRules.grapple, windupTicks: 0 } })[0]).toMatch(/^grapple\.windupTicks:/);
139	+    expect(issuesOf({ ...encounterRules, transitionTicks: 1.5 })[0]).toMatch(/^transitionTicks:/);
140	+    expect(issuesOf({ ...encounterRules, grapple: { ...encounterRules.grapple, hitConeHeadings: 33 } })[0]).toMatch(/^grapple\.hitConeHeadings:/);
141	+    expect(issuesOf({ ...encounterRules, readyTimeoutTicks: 59 })[0]).toMatch(/^readyTimeoutTicks:/);
142	+    expect(issuesOf({ ...encounterRules, drawReturnMinSeparationTiles: 13 })[0]).toMatch(/^drawReturnMinSeparationTiles:/);
143	+    expect(issuesOf({ ...encounterRules, extra: 1 })).toHaveLength(1);
144	+  });
145	+});
