158	@@ -0,0 +1,127 @@
159	+import { z } from "zod";
160	+import { formatIssues, type ValidationResult } from "../rules.js";
161	+import { ENGAGEMENT_RANGE_TILES, SIGHT_RADIUS_TILES, WORLD_STEPS_PER_SECOND } from "../sailing.js";
162	+
163	+/** §6 at sea: the grapple's telegraphed windup. */
164	+export const GRAPPLE_WINDUP_SECONDS = 1;
165	+/** §6 on islands: the visible lunge. */
166	+export const CHALLENGE_LUNGE_SECONDS = 0.6;
167	+/** §6 on islands: "close range". A placeholder until walking on islands exists. */
168	+export const CHALLENGE_RANGE_TILES = 2;
169	+/** §6: a miss costs this long before the next attempt; the grapple uses the challenge's six seconds. */
170	+export const MISS_COOLDOWN_SECONDS = 6;
171	+/** The hit area at landing: within this many headings (of 64) of the aim locked at the start, ±22.5°. */
172	+export const HIT_CONE_HEADINGS = 4;
173	+/** Target choice at the start: within this many headings of the attacker's own heading, ±45°. */
174	+export const TARGET_CONE_HEADINGS = 8;
175	+/** §14: at most this many 1v1 duels at once, counted from reservation to settlement. */
176	+export const MAX_SIMULTANEOUS_DUELS = 4;
177	+/** §6: the transition's visible countdown. */
178	+export const TRANSITION_COUNTDOWN_SECONDS = 3;
179	+/** §6: a client not ready this long after the reservation forfeits. */
180	+export const READY_TIMEOUT_SECONDS = 10;
181	+/** §2: departure protection from the start of player control. */
182	+export const SPAWN_PROTECTION_SECONDS = 45;
183	+/** §6: the winner's escape protection. */
184	+export const WIN_PROTECTION_SECONDS = 8;
185	+/** §6: a draw's (or a cancellation's) protection. */
186	+export const DRAW_PROTECTION_SECONDS = 8;
187	+/** §6: the loser respawns this long after the fight ended... */
188	+export const RESPAWN_DELAY_SECONDS = 15;
189	+/** ...with this long of protection. */
190	+export const RESPAWN_PROTECTION_SECONDS = 20;
191	+/** §6: a draw returns both players to separate points at least this far apart... */
192	+export const DRAW_RETURN_MIN_SEPARATION_TILES = 3;
193	+/** ...and within this far of the encounter. */
194	+export const DRAW_RETURN_MAX_DISTANCE_TILES = 6;
195	+
196	+/** Whole world ticks (20 a second) for a duration in seconds. */
197	+export function secondsToTicks(seconds: number): number {
198	+  return Math.round(seconds * WORLD_STEPS_PER_SECOND);
199	+}
200	+
201	+const ticks = z.int().nonnegative();
202	+const headings = z.int().min(0).max(32);
203	+
204	+/** One attack kind (§6): the sea grapple or the island challenge. */
205	+export const attackRulesSchema = z.strictObject({
206	+  /** The telegraph: the attempt lands this many ticks after it starts. At least one, so it can be escaped. */
207	+  windupTicks: z.int().positive(),
208	+  /** Centre to centre, at the start and at landing; within the sight radius, so no one attacks what they cannot see. */
209	+  rangeTiles: z.int().positive().max(SIGHT_RADIUS_TILES),
210	+  hitConeHeadings: headings,
211	+  targetConeHeadings: headings,
212	+  missCooldownTicks: ticks,
213	+});
214	+
215	+export type AttackRules = z.infer<typeof attackRulesSchema>;
216	+
217	+/** The encounter rules of §2, §6 and §14 in world ticks and tiles; the simulation converts tiles to sub-units. */
218	+export const encounterRulesSchema = z
219	+  .strictObject({
220	+    grapple: attackRulesSchema,
221	+    challenge: attackRulesSchema,
222	+    maxDuels: z.int().positive(),
223	+    transitionTicks: ticks,
224	+    readyTimeoutTicks: ticks,
225	+    spawnProtectionTicks: ticks,
226	+    winProtectionTicks: ticks,
227	+    drawProtectionTicks: ticks,
228	+    respawnDelayTicks: ticks,
229	+    respawnProtectionTicks: ticks,
230	+    /** A loser respawns at the nearest dock with no opponent this close (the sight radius, §3). */
231	+    respawnClearRadiusTiles: z.int().positive(),
232	+    drawReturnMinSeparationTiles: z.int().positive(),
233	+    drawReturnMaxDistanceTiles: z.int().positive(),
234	+  })
235	+  .superRefine((rules, ctx) => {
236	+    if (rules.readyTimeoutTicks < rules.transitionTicks) {
237	+      ctx.addIssue({
238	+        code: "custom",
239	+        path: ["readyTimeoutTicks"],
240	+        message: `the ready timeout (${rules.readyTimeoutTicks} ticks) ends before the countdown (${rules.transitionTicks} ticks)`,
241	+      });
242	+    }
243	+    if (rules.drawReturnMinSeparationTiles > 2 * rules.drawReturnMaxDistanceTiles) {
244	+      ctx.addIssue({
245	+        code: "custom",
246	+        path: ["drawReturnMinSeparationTiles"],
247	+        message: `two points within ${rules.drawReturnMaxDistanceTiles} tiles cannot be ${rules.drawReturnMinSeparationTiles} tiles apart`,
248	+      });
249	+    }
250	+  });
251	+
252	+export type EncounterRules = z.infer<typeof encounterRulesSchema>;
253	+
254	+export const encounterRules: EncounterRules = {
255	+  grapple: {
256	+    windupTicks: secondsToTicks(GRAPPLE_WINDUP_SECONDS),
257	+    rangeTiles: ENGAGEMENT_RANGE_TILES,
258	+    hitConeHeadings: HIT_CONE_HEADINGS,
259	+    targetConeHeadings: TARGET_CONE_HEADINGS,
260	+    missCooldownTicks: secondsToTicks(MISS_COOLDOWN_SECONDS),
261	+  },
262	+  challenge: {
263	+    windupTicks: secondsToTicks(CHALLENGE_LUNGE_SECONDS),
264	+    rangeTiles: CHALLENGE_RANGE_TILES,
265	+    hitConeHeadings: HIT_CONE_HEADINGS,
266	+    targetConeHeadings: TARGET_CONE_HEADINGS,
267	+    missCooldownTicks: secondsToTicks(MISS_COOLDOWN_SECONDS),
268	+  },
269	+  maxDuels: MAX_SIMULTANEOUS_DUELS,
270	+  transitionTicks: secondsToTicks(TRANSITION_COUNTDOWN_SECONDS),
271	+  readyTimeoutTicks: secondsToTicks(READY_TIMEOUT_SECONDS),
272	+  spawnProtectionTicks: secondsToTicks(SPAWN_PROTECTION_SECONDS),
273	+  winProtectionTicks: secondsToTicks(WIN_PROTECTION_SECONDS),
274	+  drawProtectionTicks: secondsToTicks(DRAW_PROTECTION_SECONDS),
275	+  respawnDelayTicks: secondsToTicks(RESPAWN_DELAY_SECONDS),
276	+  respawnProtectionTicks: secondsToTicks(RESPAWN_PROTECTION_SECONDS),
277	+  respawnClearRadiusTiles: SIGHT_RADIUS_TILES,
278	+  drawReturnMinSeparationTiles: DRAW_RETURN_MIN_SEPARATION_TILES,
279	+  drawReturnMaxDistanceTiles: DRAW_RETURN_MAX_DISTANCE_TILES,
280	+};
281	+
282	+export function validateEncounterRules(candidate: unknown): ValidationResult<EncounterRules> {
283	+  const parsed = encounterRulesSchema.safeParse(candidate);
284	+  return parsed.success ? { ok: true, value: parsed.data } : { ok: false, issues: formatIssues(parsed.error) };
285	+}
