308	+import { createSeaMap, HEADING_COUNT, isNavigable, seaMap, type SeaMapDefinition } from "@pirate-sea-race/content";
309	+import { describe, expect, it } from "vitest";
310	+import { nextInt } from "../random.js";
311	+import {
312	+  bearing,
313	+  createEncounterConfig,
314	+  createEncounterState,
315	+  ENCOUNTER_EVENT_KINDS,
316	+  encounterRules,
317	+  hashState,
318	+  stepEncounters,
319	+  tileCentre,
320	+  tileOf,
321	+  type DuelReport,
322	+  type EncounterConfig,
323	+  type EncounterEvent,
324	+  type EncounterMode,
325	+  type EncounterPlayerInput,
326	+  type EncounterState,
327	+  type EncounterTickInput,
328	+} from "./index.js";
329	+
330	+type Draw = (bound: number) => number;
331	+
332	+function generator(seed: number): Draw {
333	+  let rng = seed;
334	+  return (bound) => {
335	+    const drawn = nextInt(rng, bound);
336	+    rng = drawn.state;
337	+    return drawn.value;
338	+  };
339	+}
340	+
341	+function shuffled<T>(items: readonly T[], draw: Draw): T[] {
342	+  const copy = [...items];
343	+  for (let index = copy.length - 1; index > 0; index--) {
344	+    const other = draw(index + 1);
345	+    [copy[index], copy[other]] = [copy[other]!, copy[index]!];
346	+  }
347	+  return copy;
348	+}
349	+
350	+/** A small synthetic sea: scattered land and shoals, and a dock on each side. */
351	+function syntheticSea(seed: number, size: number): SeaMapDefinition {
352	+  const draw = generator(seed);
353	+  const rows = Array.from({ length: size }, (_, row) =>
354	+    Array.from({ length: size }, (_, column) => {
355	+      if ((row === 1 && column === Math.floor(size / 2)) || (row === size - 2 && column === 2) || (column === size - 2 && row === 3)) return "D";
356	+      const roll = draw(100);
357	+      return roll < 7 ? "#" : roll < 12 ? "%" : ".";
