654	+function renamer(rename: (id: string) => string, ids: ReadonlySet<string>) {
655	+  const renameString = (value: string): string => {
656	+    if (ids.has(value)) return rename(value);
657	+    const match = /^duel:(\d+):(\d+):(.*)$/.exec(value);
658	+    if (match === null) return value;
659	+    const length = Number(match[2]);
660	+    const attacker = match[3]!.slice(0, length);
661	+    const defender = match[3]!.slice(length + 1);
662	+    const renamed = rename(attacker);
663	+    return `duel:${match[1]}:${renamed.length}:${renamed}:${rename(defender)}`;
664	+  };
665	+  const walk = (value: unknown): unknown => {
666	+    if (typeof value === "string") return renameString(value);
667	+    if (Array.isArray(value)) return value.map(walk);
668	+    if (value !== null && typeof value === "object") return Object.fromEntries(Object.entries(value).map(([key, inner]) => [key, walk(inner)]));
669	+    return value;
670	+  };
671	+  return walk;
