773	+  step(options: TickOptions = {}): EncounterEvent[] {
774	+    const press = new Set(options.press ?? []);
775	+    const players = [...this.players.values()].map((player) => ({ ...player, attack: press.has(player.id) }));
776	+    const result = stepEncounters(this.cfg, this.state, { tick: this.state.tick + 1, players, reports: options.reports ?? [], matchOver: options.matchOver ?? false });
777	+    this.state = result.state;
778	+    this.log.push(...result.events);
779	+    // Reported protection ends are one-tick signals.
780	+    for (const player of this.players.values()) if (player.protectionEndedBy !== null) this.set(player.id, { protectionEndedBy: null });
781	+    return [...result.events];
782	+  }
783	+
784	+  /** Steps until `tick` has been processed, returning every event on the way. */
785	+  runTo(tick: number): EncounterEvent[] {
786	+    const events: EncounterEvent[] = [];
787	+    while (this.state.tick < tick) events.push(...this.step());
788	+    return events;
789	+  }
790	+
791	+  record(id: string) {
792	+    return this.state.players.find((player) => player.id === id);
793	+  }
794	+}
795	+
796	+const kinds = (events: readonly EncounterEvent[]) => events.map((event) => event.kind);
797	+const started = (events: readonly EncounterEvent[]) => events.filter((event) => event.kind === "attempt-started");
798	+const ofKind = <K extends EncounterEvent["kind"]>(events: readonly EncounterEvent[], kind: K) =>
799	+  events.filter((event): event is Extract<EncounterEvent, { kind: K }> => event.kind === kind);
800	+
801	+/** Presses once on tick 1 and runs to the landing tick (21). */
802	+function grapple(world: World, attacker: string): EncounterEvent[] {
803	+  const events = world.step({ press: [attacker] });
804	+  return [...events, ...world.runTo(1 + config.modes.ship.windupTicks)];
805	+}
806	+
807	+describe("starting an attempt (§6)", () => {
808	+  it("picks the nearest eligible ship in range, line of sight and the front cone, and locks the aim toward it", () => {
809	+    const world = new World([ship("a", 5, 12), ship("far", 9, 12), ship("near", 8, 12), ship("behind", 3, 12)]);
810	+    const events = world.step({ press: ["a"] });
811	+    expect(events).toEqual([{ kind: "attempt-started", tick: 1, attackerId: "a", defenderId: "near", mode: "ship", aim: 0, landTick: 21 }]);
812	+    expect(world.state.attempts).toEqual([{ attackerId: "a", defenderId: "near", mode: "ship", aim: 0, startTick: 1, landTick: 21 }]);
813	+  });
814	+
815	+  it("takes a target at the ±8 cone's edge and not one just outside it", () => {
816	+    // (2, -2) tiles is heading 56, 8 off heading 0; (1, -2) is heading 53, 11 off.
817	+    const edge = new World([ship("a", 5, 12), ship("edge", 7, 10), ship("ahead", 9, 12)]);
818	+    expect(started(edge.step({ press: ["a"] }))[0]).toMatchObject({ defenderId: "edge", aim: 56 });
819	+    const outside = new World([ship("a", 5, 12), ship("steep", 6, 10), ship("ahead", 9, 12)]);
820	+    expect(started(outside.step({ press: ["a"] }))[0]).toMatchObject({ defenderId: "ahead", aim: 0 });
821	+  });
822	+
823	+  it("reaches exactly the grapple range and not one sub-unit further", () => {
824	+    const world = new World([ship("a", 5, 12), { ...ship("b", 11, 12), x: at(5, 12).x + 6 * TILE + 1 }]);
825	+    expect(world.step({ press: ["a"] })).toEqual([]);
826	+    world.set("b", { x: at(5, 12).x + 6 * TILE });
827	+    expect(started(world.step({ press: ["a"] }))[0]).toMatchObject({ defenderId: "b" });
828	+  });
829	+
830	+  it("passes over a nearer ship behind land, but not one behind a shoal", () => {
831	+    // Land at column 20 rows 3–6; a shoal at (20, 10).
832	+    const land = new World([ship("a", 17, 5), ship("hidden", 22, 5), ship("seen", 17, 9, 16)]);
833	+    land.set("a", { heading: 0 });
834	+    expect(land.step({ press: ["a"] })).toEqual([]);
835	+    const shoal = new World([ship("a", 17, 10), ship("reef", 22, 10)]);
836	+    expect(started(shoal.step({ press: ["a"] }))[0]).toMatchObject({ defenderId: "reef" });
837	+  });
838	+
839	+  it("breaks a distance tie to the lower id, wherever the players stand and whatever order they arrive in", () => {
840	+    for (const [first, second] of [
841	+      ["zed", "bob"],
842	+      ["bob", "zed"],
843	+    ] as const) {
844	+      const world = new World([ship(first, 8, 11), ship("a", 5, 12), ship(second, 8, 13)]);
845	+      expect(started(world.step({ press: ["a"] }))[0]).toMatchObject({ defenderId: "bob" });
846	+    }
847	+  });
848	+
849	+  it("starts nothing and costs nothing when a press finds no target", () => {
850	+    const world = new World([ship("a", 5, 12), ship("b", 12, 12)], { spawnProtected: ["a"] });
851	+    expect(world.step({ press: ["a"] })).toEqual([]);
852	+    expect(world.state.attempts).toEqual([]);
853	+    // No cooldown and the attacker keeps their protection.
854	+    expect(world.record("a")).toEqual({ id: "a", protection: { source: "spawn", endTick: 900 }, cooldownEndTick: 0, respawn: null });
855	+    world.set("b", { ...at(10, 12) });
856	+    expect(kinds(world.step({ press: ["a"] }))).toEqual(["protection-ended", "attempt-started"]);
857	+  });
858	+
859	+  it("ignores a press while the player's own attempt winds up", () => {
860	+    const world = new World([ship("a", 5, 12), ship("b", 7, 12), ship("c", 6, 12)]);
861	+    world.step({ press: ["a"] });
862	+    expect(world.step({ press: ["a"] })).toEqual([]);
863	+    expect(world.state.attempts).toHaveLength(1);
864	+  });
865	+});
866	+
867	+describe("escape (§6)", () => {
868	+  it("lands a hit on a defender who stayed", () => {
869	+    const world = new World([ship("a", 5, 12), ship("b", 8, 12)]);
870	+    const events = grapple(world, "a");
871	+    expect(ofKind(events, "duel-reserved")).toEqual([
872	+      { kind: "duel-reserved", tick: 21, duelId: "duel:21:1:a:b", mode: "ship", players: ["a", "b"], x: Math.floor((at(5, 12).x + at(8, 12).x) / 2), y: at(5, 12).y },
873	+    ]);
874	+    expect(world.state.attempts).toEqual([]);
875	+  });
876	+
877	+  it("misses a defender who left the range, costing the attacker the cooldown", () => {
878	+    const world = new World([ship("a", 5, 12), ship("b", 8, 12)]);
879	+    world.step({ press: ["a"] });
880	+    world.runTo(20);
881	+    world.set("b", at(12, 12));
882	+    expect(world.step()).toEqual([{ kind: "attempt-missed", tick: 21, attackerId: "a", defenderId: "b", reason: "out-of-range", cooldownEndTick: 141 }]);
883	+  });
884	+
885	+  it("misses a defender who left the aim, even within range", () => {
886	+    const world = new World([ship("a", 5, 12), ship("b", 8, 12)]);
887	+    world.step({ press: ["a"] });
888	+    world.runTo(20);
889	+    // (3, -3) tiles: heading 56, 8 off the locked aim of 0.
890	+    world.set("b", at(8, 9));
891	+    expect(ofKind(world.step(), "attempt-missed")[0]).toMatchObject({ reason: "out-of-aim" });
892	+  });
893	+
894	+  it("misses a defender who slipped behind land", () => {
895	+    const world = new World([ship("a", 16, 7), ship("b", 21, 7)]);
896	+    world.step({ press: ["a"] });
897	+    world.runTo(20);
898	+    // (5, -1) tiles: heading 62, inside the aim, but the line crosses the land at (20, 6).
899	+    world.set("b", at(21, 6));
900	+    expect(ofKind(world.step(), "attempt-missed")[0]).toMatchObject({ reason: "no-line-of-sight" });
901	+  });
902	+
903	+  it("follows the aim while the defender stays inside it: moving within ±4 headings is no escape", () => {
904	+    const world = new World([ship("a", 5, 12), ship("b", 9, 12)]);
905	+    world.step({ press: ["a"] });
906	+    world.runTo(20);
907	+    world.set("b", at(9, 11)); // (4, -1): heading 60, 4 off.
908	+    expect(kinds(world.step())).toEqual(["duel-reserved"]);
909	+  });
910	+});
911	+
912	+describe("cooldown on a miss only", () => {
913	+  it("refuses presses until the six seconds are over, then starts again", () => {
914	+    const world = new World([ship("a", 5, 12), ship("b", 8, 12)]);
915	+    world.step({ press: ["a"] });
916	+    world.runTo(20);
917	+    world.set("b", at(12, 12));
918	+    world.step();
919	+    world.set("b", at(8, 12));
920	+    for (let tick = 22; tick < 141; tick++) expect(world.step({ press: ["a"] })).toEqual([]);
921	+    expect(world.record("a")?.cooldownEndTick).toBe(141);
922	+    expect(started(world.step({ press: ["a"] }))).toHaveLength(1);
923	+    expect(world.tick).toBe(141);
924	+    // A record with nothing left to remember is dropped.
925	+    expect(world.record("a")).toBeUndefined();
926	+  });
927	+
928	+  it("costs nothing for a preempted hit or a cancelled attempt", () => {
929	+    // b's attempt on c loses to a's closer hit on b, so b is reserved: a preemption.
930	+    const world = new World([ship("a", 5, 12), ship("b", 7, 12), ship("c", 10, 12), ship("d", 5, 20), ship("e", 7, 20)]);
931	+    world.step({ press: ["a", "b", "d"] });
