1	import { HEADING_COUNT } from "@pirate-sea-race/content";
2	import { hashState } from "../hash.js";
3	import { bearing, distanceSquared, withinCone, withinRange, type EncounterPoint } from "./geometry.js";
4	import {
5	  compareDuels,
6	  compareIds,
7	  duelIdFor,
8	  ENCOUNTER_MODES,
9	  type DuelReport,
10	  type EncounterAttempt,
11	  type EncounterConfig,
12	  type EncounterDuel,
13	  type EncounterEvent,
14	  type EncounterPlayer,
15	  type EncounterPlayerInput,
16	  type EncounterState,
17	  type EncounterStepResult,
18	  type EncounterTickInput,
19	  type MissReason,
20	  type Protection,
21	} from "./state.js";
22	
23	function requireInteger(value: unknown, name: string): void {
24	  if (typeof value !== "number" || !Number.isSafeInteger(value)) throw new RangeError(`${name} must be a safe integer, got ${String(value)}`);
25	}
26	
27	function requireBoolean(value: unknown, name: string): void {
28	  if (typeof value !== "boolean") throw new RangeError(`${name} must be a boolean, got ${String(value)}`);
29	}
30	
31	function requireId(value: unknown, name: string): void {
32	  if (typeof value !== "string" || value.length === 0) throw new RangeError(`${name} must be a non-empty string`);
33	}
34	
35	/** Refuses a malformed tick: a skipped or repeated tick, duplicate ids, a field of the wrong type. */
36	function readInput(state: EncounterState, input: EncounterTickInput): Map<string, EncounterPlayerInput> {
37	  requireInteger(input.tick, "tick");
38	  if (input.tick !== state.tick + 1) throw new RangeError(`expected tick ${state.tick + 1}, got ${input.tick}`);
39	  requireBoolean(input.matchOver, "matchOver");
40	  const players = new Map<string, EncounterPlayerInput>();
41	  for (const player of input.players) {
42	    requireId(player.id, "player id");
43	    if (players.has(player.id)) throw new RangeError(`player ${player.id} appears twice`);
44	    if (!ENCOUNTER_MODES.includes(player.mode)) throw new RangeError(`${player.id}.mode must be ship or foot`);
45	    requireInteger(player.x, `${player.id}.x`);
46	    requireInteger(player.y, `${player.id}.y`);
47	    requireInteger(player.heading, `${player.id}.heading`);
48	    if (player.heading < 0 || player.heading >= HEADING_COUNT) throw new RangeError(`${player.id}.heading must be in [0, ${HEADING_COUNT})`);
49	    for (const flag of ["connected", "attack", "ready"] as const) requireBoolean(player[flag], `${player.id}.${flag}`);
50	    if (player.protectionEndedBy !== null && player.protectionEndedBy !== "claim" && player.protectionEndedBy !== "collection") {
51	      throw new RangeError(`${player.id}.protectionEndedBy must be claim, collection or null`);
52	    }
53	    players.set(player.id, player);
54	  }
55	  for (const report of input.reports) {
56	    requireId(report.duelId, "report duelId");
57	    requireInteger(report.tick, `report ${report.duelId} tick`);
58	    if (report.kind !== "end" && report.kind !== "settled") throw new RangeError(`report ${String((report as DuelReport).duelId)} has an unknown kind`);
59	  }
60	  return players;
61	}
62	
63	/**
64	 * A total order on reports that neither input order nor an order-preserving relabelling of players changes: reports
65	 * on known duels in duel order, then the rest by id; for one duel, ends before settlements, then by content, so the
66	 * first of two conflicting reports on one tick is always the same one.
67	 */
68	function compareReports(duels: ReadonlyMap<string, EncounterDuel>, a: DuelReport, b: DuelReport): number {
69	  const duelA = duels.get(a.duelId);
70	  const duelB = duels.get(b.duelId);
71	  if (duelA !== undefined && duelB !== undefined && duelA !== duelB) return compareDuels(duelA, duelB);
72	  if (duelA === undefined || duelB === undefined) {
73	    if (duelA !== duelB) return duelA === undefined ? 1 : -1;
74	    const byId = compareIds(a.duelId, b.duelId);
75	    if (byId !== 0) return byId;
76	  }
77	  const detail = (report: DuelReport) =>
78	    JSON.stringify(report.kind === "end" ? [0, report.tick, report.outcome, "winner" in report ? report.winner : null] : [1, report.tick]);
79	  return compareIds(detail(a), detail(b));
80	}
81	
82	const byAttacker = (a: EncounterAttempt, b: EncounterAttempt) => compareIds(a.attackerId, b.attackerId);
83	
84	/**
85	 * One world tick of §6's encounter rules. The caller runs it before the claim channel (§5), with the previous tick's
86	 * claim and ledger results in `protectionEndedBy`. In a fixed order: (0) a match reported over cancels every attempt
87	 * and freezes the state; (1) protection expires or ends by an objective; (2) duel reports: ends, then settlements with
88	 * their returns; (3) losers due to respawn respawn; (4) transitions start or time out; (5) attempts whose attacker is
89	 * no longer eligible are cancelled, and every attempt landing on this tick resolves together: misses, then hits by
90	 * distance, attacker id and defender id, each reserving a duel while both players are free and the cap allows;
91	 * (6) presses start new attempts. Players, attempts and reports are read as sets, so their order in the input never
92	 * matters. The input state is never mutated.
93	 */
94	export function stepEncounters(config: EncounterConfig, state: EncounterState, input: EncounterTickInput): EncounterStepResult {
95	  if (state.closed) return { state, events: [] };
96	  const snapshot = readInput(state, input);
97	  const tick = input.tick;
98	  const events: EncounterEvent[] = [];
99	
100	  let attempts = [...state.attempts].sort(byAttacker);
101	
102	  // 0. The match is over: nothing lands, nothing starts. Running duels end through the claim code (§2).
103	  if (input.matchOver) {
104	    for (const attempt of attempts) {
105	      events.push({ kind: "attempt-cancelled", tick, attackerId: attempt.attackerId, defenderId: attempt.defenderId, reason: "match-over" });
106	    }
107	    return { state: { ...state, tick, closed: true, attempts: [] }, events };
108	  }
109	
110	  const records = new Map<string, EncounterPlayer>(state.players.map((player) => [player.id, player]));
111	  const record = (id: string): EncounterPlayer => records.get(id) ?? { id, protection: null, cooldownEndTick: 0, respawn: null };
112	  const update = (id: string, change: Partial<Omit<EncounterPlayer, "id">>) => records.set(id, { ...record(id), ...change });
113	  const sortedIds = () => [...records.keys()].sort(compareIds);
114	
115	  // 1. Protection ends when it runs out, or when last tick's claim or collection ended it (§6).
116	  for (const id of sortedIds()) {
117	    const protection = record(id).protection;
118	    if (protection === null) continue;
119	    const endedBy = snapshot.get(id)?.protectionEndedBy ?? null;
120	    if (tick >= protection.endTick || endedBy !== null) {
121	      update(id, { protection: null });
122	      events.push({ kind: "protection-ended", tick, playerId: id, reason: tick >= protection.endTick ? "expired" : endedBy! });
123	    }
124	  }
125	
126	  // 2. Reports: an end once per duel, then the ledger's settlement, which returns the players.
127	  const duels = new Map<string, EncounterDuel>(state.duels.map((duel) => [duel.id, duel]));
128	  const reports = [...input.reports].sort((a, b) => compareReports(duels, a, b));
129	  for (const report of reports) {
130	    const duel = duels.get(report.duelId);
131	    const refuse = (reason: "unknown-duel" | "already-ended" | "not-ended" | "invalid") =>
132	      events.push({ kind: "report-refused", tick, duelId: report.duelId, report: report.kind, reason });
133	    if (duel === undefined) {
134	      refuse("unknown-duel");
135	    } else if (report.kind === "end") {
136	      if (duel.end !== null) {
137	        refuse("already-ended");
138	        continue;
139	      }
140	      const winner = report.outcome === "win" ? report.winner : null;
141	      const valid =
142	        report.tick >= duel.reservedTick &&
143	        report.tick <= tick &&
144	        (report.outcome === "win"
145	          ? duel.players.includes(report.winner)
146	          : (report.outcome === "draw" || report.outcome === "cancelled") && (report as { winner?: unknown }).winner === undefined);
147	      if (!valid) {
148	        refuse("invalid");
149	        continue;
150	      }
151	      const loser = winner === null ? null : duel.players[0] === winner ? duel.players[1] : duel.players[0];
152	      duels.set(duel.id, { ...duel, phase: "ended", end: { tick: report.tick, outcome: report.outcome, winner, loser, cause: "report" } });
153	      events.push({ kind: "duel-ended", tick, duelId: duel.id, outcome: report.outcome, winner, endTick: report.tick });
154	    } else {
155	      const end = duel.end;
156	      if (end === null) {
157	        refuse("not-ended");
158	        continue;
159	      }
160	      if (report.tick < end.tick || report.tick > tick) {
161	        refuse("invalid");
162	        continue;
163	      }
164	      duels.delete(duel.id);
165	      events.push({ kind: "duel-settled", tick, duelId: duel.id });
166	      settle(config, duel, end, report.tick, tick, events, update);
167	    }
168	  }
169	
170	  // 3. Losers whose 15 s have run respawn at a dock away from opponents, chosen from this tick's positions.
171	  const respawning = new Set(sortedIds().filter((id) => record(id).respawn !== null));
172	  for (const id of [...respawning]) {
173	    const respawn = record(id).respawn!;
174	    if (respawn.respawnTick > tick) continue;
175	    const opponents = [...snapshot.values()]
176	      .filter((player) => player.id !== id && !respawning.has(player.id))
177	      .sort((a, b) => compareIds(a.id, b.id))
178	      .map((player) => ({ x: player.x, y: player.y }));
179	    const point = config.modes[respawn.mode].rules.respawnPoint({
180	      encounter: { x: respawn.x, y: respawn.y },
181	      own: { x: respawn.ownX, y: respawn.ownY },
182	      opponents,
183	      clearRadius: config.respawnClearRadius,
184	    });
185	    const protection: Protection = { source: "respawn", endTick: tick + config.respawnProtectionTicks };
186	    update(id, { respawn: null, protection: protection.endTick > tick ? protection : null });
187	    events.push({ kind: "player-respawned", tick, playerId: id, x: point.x, y: point.y, dockId: point.dockId, protection });
188	  }
189	
190	  // 4. Transitions: the fight starts after the countdown with both clients ready; at the timeout, the unready forfeit.
191	  for (const { id } of [...duels.values()].sort(compareDuels)) {
192	    const duel = duels.get(id)!;
193	    if (duel.phase !== "transition") continue;
194	    const ready = duel.players.map((playerId) => snapshot.get(playerId)?.ready === true);
195	    if (tick >= duel.reservedTick + config.transitionTicks && ready[0] && ready[1]) {
196	      duels.set(id, { ...duel, phase: "fighting", startTick: tick });
197	      events.push({ kind: "duel-started", tick, duelId: id });
198	    } else if (tick >= duel.reservedTick + config.readyTimeoutTicks) {
199	      if (!ready[0] && !ready[1]) {
200	        duels.set(id, { ...duel, phase: "ended", end: { tick, outcome: "cancelled", winner: null, loser: null, cause: "readiness" } });
201	        events.push({ kind: "duel-cancelled", tick, duelId: id });
202	      } else {
203	        const [winner, loser] = ready[0] ? [duel.players[0], duel.players[1]] : [duel.players[1], duel.players[0]];
204	        duels.set(id, { ...duel, phase: "ended", end: { tick, outcome: "win", winner, loser, cause: "readiness" } });
205	        events.push({ kind: "duel-forfeited", tick, duelId: id, forfeiter: loser, winner });
206	      }
207	    }
208	  }
209	
210	  const inDuel = new Set<string>();
211	  for (const duel of duels.values()) for (const playerId of duel.players) inDuel.add(playerId);
212	  const isRespawning = (id: string) => record(id).respawn !== null;
213	  const isProtected = (id: string) => record(id).protection !== null;
214	  /** In the match, of this mode, free of duels and respawns; protection and the cap are checked by the caller of this. */
215	  const free = (id: string, mode: EncounterPlayerInput["mode"]) => {
216	    const player = snapshot.get(id);
217	    return player !== undefined && player.mode === mode && !inDuel.has(id) && !isRespawning(id);
218	  };
219	  const cancel = (attempt: EncounterAttempt, reason: "attacker-ineligible") =>
220	    events.push({ kind: "attempt-cancelled", tick, attackerId: attempt.attackerId, defenderId: attempt.defenderId, reason });
221	
222	  // 5a. An attacker who left, disconnected, changed mode, or was reserved or respawns loses the attempt, no cooldown.
223	  attempts = attempts.filter((attempt) => {
224	    const keep = free(attempt.attackerId, attempt.mode) && snapshot.get(attempt.attackerId)!.connected;
225	    if (!keep) cancel(attempt, "attacker-ineligible");
226	    return keep;
227	  });
228	
229	  // 5b. Everything landing on this tick resolves together (§5): misses first, then hits in a fixed order.
230	  const hits: { attempt: EncounterAttempt; distance: number; attacker: EncounterPoint; defender: EncounterPoint }[] = [];
231	  for (const attempt of attempts) {
232	    if (attempt.landTick !== tick) continue;
233	    const mode = config.modes[attempt.mode];
234	    const attacker = snapshot.get(attempt.attackerId)!;
235	    const defender = snapshot.get(attempt.defenderId);
236	    let reason: MissReason | null = null;
237	    if (defender === undefined || !free(defender.id, attempt.mode) || isProtected(defender.id)) reason = "defender-ineligible";
238	    else if (!withinRange(attacker, defender, mode.range)) reason = "out-of-range";
239	    else if (!withinCone(attacker, defender, attempt.aim, mode.hitConeHeadings)) reason = "out-of-aim";
240	    else if (!mode.rules.lineOfSight(attacker, defender)) reason = "no-line-of-sight";
241	    if (reason === null) {
242	      hits.push({ attempt, distance: distanceSquared(attacker, defender!), attacker, defender: defender! });
243	    } else {
244	      const cooldownEndTick = tick + mode.missCooldownTicks;
245	      update(attempt.attackerId, { cooldownEndTick });
246	      events.push({ kind: "attempt-missed", tick, attackerId: attempt.attackerId, defenderId: attempt.defenderId, reason, cooldownEndTick });
247	    }
248	  }
249	  hits.sort(
250	    (a, b) => a.distance - b.distance || compareIds(a.attempt.attackerId, b.attempt.attackerId) || compareIds(a.attempt.defenderId, b.attempt.defenderId),
251	  );
252	  for (const { attempt, attacker, defender } of hits) {
253	    const { attackerId, defenderId } = attempt;
254	    if (inDuel.has(attackerId) || inDuel.has(defenderId)) {
255	      events.push({ kind: "attempt-preempted", tick, attackerId, defenderId, reason: "conflict" });
256	    } else if (duels.size >= config.maxDuels) {
257	      events.push({ kind: "attempt-preempted", tick, attackerId, defenderId, reason: "duel-cap" });
258	    } else {
259	      const id = duelIdFor(tick, attackerId, defenderId);
260	      const x = Math.floor((attacker.x + defender.x) / 2);
261	      const y = Math.floor((attacker.y + defender.y) / 2);
262	      duels.set(id, {
263	        id,
264	        mode: attempt.mode,
265	        players: [attackerId, defenderId],
266	        positions: [
267	          { x: attacker.x, y: attacker.y },
268	          { x: defender.x, y: defender.y },
269	        ],
270	        x,
271	        y,
272	        reservedTick: tick,
273	        phase: "transition",
274	        startTick: null,
275	        end: null,
276	      });
277	      inDuel.add(attackerId);
278	      inDuel.add(defenderId);
279	      events.push({ kind: "duel-reserved", tick, duelId: id, mode: attempt.mode, players: [attackerId, defenderId], x, y });
280	    }
281	  }
282	  attempts = attempts.filter((attempt) => {
283	    if (attempt.landTick === tick) return false;
284	    // A player just reserved as a defender loses their own attempt.
285	    if (!inDuel.has(attempt.attackerId)) return true;
286	    cancel(attempt, "attacker-ineligible");
287	    return false;
288	  });
289	
290	  // 6. Presses. Every target is chosen from the state before any of this tick's starts, so a protected player who
291	  // attacks on this tick is still not a target on it, whatever order the presses arrive in.
292	  const attacking = new Set(attempts.map((attempt) => attempt.attackerId));
293	  const started: EncounterAttempt[] = [];
294	  const protectedBefore = new Set([...records.values()].filter((player) => player.protection !== null).map((player) => player.id));
295	  if (duels.size < config.maxDuels) {
296	    const players = [...snapshot.values()].sort((a, b) => compareIds(a.id, b.id));
297	    for (const attacker of players) {
298	      if (!attacker.attack || !attacker.connected || attacking.has(attacker.id) || !free(attacker.id, attacker.mode)) continue;
299	      if (tick < record(attacker.id).cooldownEndTick) continue;
300	      const mode = config.modes[attacker.mode];
301	      let target: { player: EncounterPlayerInput; distance: number } | null = null;
302	      for (const defender of players) {
303	        if (defender.id === attacker.id || !free(defender.id, attacker.mode) || protectedBefore.has(defender.id)) continue;
304	        if (!withinRange(attacker, defender, mode.range) || !withinCone(attacker, defender, attacker.heading, mode.targetConeHeadings)) continue;
305	        if (!mode.rules.lineOfSight(attacker, defender)) continue;
306	        // Players are in id order, so a strictly nearer one replaces the choice and an equal one never does.
307	        const distance = distanceSquared(attacker, defender);
308	        if (target === null || distance < target.distance) target = { player: defender, distance };
309	      }
310	      if (target === null) continue;
311	      if (protectedBefore.has(attacker.id)) {
312	        update(attacker.id, { protection: null });
313	        events.push({ kind: "protection-ended", tick, playerId: attacker.id, reason: "attack" });
314	      }
315	      const aim = bearing(attacker, target.player) ?? attacker.heading;
316	      const attempt: EncounterAttempt = {
317	        attackerId: attacker.id,
318	        defenderId: target.player.id,
319	        mode: attacker.mode,
320	        aim,
321	        startTick: tick,
322	        landTick: tick + mode.windupTicks,
323	      };
324	      started.push(attempt);
325	      events.push({ kind: "attempt-started", tick, attackerId: attacker.id, defenderId: target.player.id, mode: attacker.mode, aim, landTick: attempt.landTick });
326	    }
327	  }
328	
329	  // Records with nothing left to remember are dropped, so equal situations hash equally.
330	  const players = sortedIds()
331	    .map(record)
332	    .filter((player) => player.protection !== null || player.cooldownEndTick > tick || player.respawn !== null)
333	    .map((player) => (player.cooldownEndTick > tick ? player : { ...player, cooldownEndTick: 0 }));
334	  return {
335	    state: {
336	      tick,
337	      closed: false,
338	      players,
339	      attempts: [...attempts, ...started].sort(byAttacker),
340	      duels: [...duels.values()].sort(compareDuels),
341	    },
342	    events,
343	  };
344	}
345	
346	/** §6's return at settlement: the winner stays with 8 s, the loser waits to respawn, a draw separates both. */
347	function settle(
348	  config: EncounterConfig,
349	  duel: EncounterDuel,
350	  end: NonNullable<EncounterDuel["end"]>,
351	  settledTick: number,
352	  tick: number,
353	  events: EncounterEvent[],
354	  update: (id: string, change: Partial<Omit<EncounterPlayer, "id">>) => void,
355	): void {
356	  const guard = (protection: Protection) => (protection.endTick > tick ? protection : null);
357	  const returned = (playerId: string, point: EncounterPoint, protection: Protection) => {
358	    update(playerId, { protection: guard(protection) });
359	    events.push({ kind: "player-returned", tick, duelId: duel.id, playerId, x: point.x, y: point.y, protection });
360	  };
361	  if (end.outcome === "win") {
362	    const winner = end.winner!;
363	    const loser = end.loser!;
364	    const own = duel.positions[duel.players.indexOf(winner)]!;
365	    returned(winner, own, { source: "win", endTick: settledTick + config.winProtectionTicks });
366	    // The respawn counts from the fight's end, not the settlement, so the theft choice does not lengthen it.
367	    const respawnTick = Math.max(end.tick + config.respawnDelayTicks, tick);
368	    const loserOwn = duel.positions[duel.players.indexOf(loser)]!;
369	    update(loser, {
370	      protection: null,
371	      respawn: { duelId: duel.id, respawnTick, x: duel.x, y: duel.y, ownX: loserOwn.x, ownY: loserOwn.y, mode: duel.mode },
372	    });
373	    events.push({ kind: "player-respawning", tick, duelId: duel.id, playerId: loser, respawnTick });
374	    return;
375	  }
376	  const points = config.modes[duel.mode].rules.separateReturn({
377	    encounter: { x: duel.x, y: duel.y },
378	    players: duel.positions,
379	    minSeparation: config.drawReturnMinSeparation,
380	    maxDistance: config.drawReturnMaxDistance,
381	  });
382	  const protection: Protection = { source: "draw", endTick: settledTick + config.drawProtectionTicks };
383	  returned(duel.players[0], points[0], protection);
384	  returned(duel.players[1], points[1], protection);
385	}
386	
387	export interface EncounterReplay {
388	  readonly state: EncounterState;
389	  readonly events: readonly EncounterEvent[];
390	  readonly hash: string;
391	}
392	
393	/** Steps a sequence of ticks from a state, collecting every event; `hash` is the final state's `hashState`. */
394	export function replayEncounters(config: EncounterConfig, state: EncounterState, inputs: readonly EncounterTickInput[]): EncounterReplay {
395	  let current = state;
396	  const events: EncounterEvent[] = [];
397	  for (const input of inputs) {
398	    const stepped = stepEncounters(config, current, input);
399	    current = stepped.state;
400	    events.push(...stepped.events);
401	  }
402	  return { state: current, events, hash: hashState(current) };
403	}
