1359	+      let empty = false;
1360	+      for (const [origin, delta, cell] of [
1361	+        [x0, dx, tileX],
1362	+        [y0, dy, tileY],
1363	+      ] as const) {
1364	+        const [min, max] = [2 * cell, 2 * cell + 2];
