1517	+import { HEADING_COUNT, Terrain, terrainAt, type SeaMapDefinition } from "@pirate-sea-race/content";
1518	+import { HEADING_DX, HEADING_DY, normalizeHeading } from "../heading.js";
1519	+
1520	+/**
1521	+ * The encounter geometry, defined once (docs/encounters.md): integer sub-units, squared distances, the 64-heading
1522	+ * table. Nothing here rounds a fraction or calls a transcendental function.
1523	+ */
1524	+
1525	+/** A point in integer sub-units. */
1526	+export interface EncounterPoint {
1527	+  readonly x: number;
1528	+  readonly y: number;
1529	+}
1530	+
1531	+/** Squared distance, refusing coordinates whose square would not be an exact integer. */
1532	+export function distanceSquared(from: EncounterPoint, to: EncounterPoint): number {
1533	+  const dx = to.x - from.x;
1534	+  const dy = to.y - from.y;
1535	+  const squared = dx * dx + dy * dy;
1536	+  if (!Number.isSafeInteger(squared)) throw new RangeError(`(${from.x}, ${from.y}) and (${to.x}, ${to.y}) are too far apart`);
1537	+  return squared;
1538	+}
1539	+
1540	+/** Within `range` sub-units, centre to centre; a point exactly on the boundary is inside. */
1541	+export function withinRange(from: EncounterPoint, to: EncounterPoint, range: number): boolean {
1542	+  return distanceSquared(from, to) <= range * range;
1543	+}
1544	+
1545	+/**
1546	+ * The heading (of 64) pointing most nearly along the offset: the one whose unit vector has the largest dot product
1547	+ * with it, ties to the lower heading. A zero offset has no bearing (null).
1548	+ */
1549	+export function bearing(from: EncounterPoint, to: EncounterPoint): number | null {
1550	+  const dx = to.x - from.x;
1551	+  const dy = to.y - from.y;
1552	+  if (dx === 0 && dy === 0) return null;
1553	+  let best = 0;
1554	+  let bestDot = dx * HEADING_DX[0]! + dy * HEADING_DY[0]!;
1555	+  for (let heading = 1; heading < HEADING_COUNT; heading++) {
1556	+    const dot = dx * HEADING_DX[heading]! + dy * HEADING_DY[heading]!;
1557	+    if (dot > bestDot) {
1558	+      best = heading;
1559	+      bestDot = dot;
1560	+    }
1561	+  }
1562	+  return best;
1563	+}
1564	+
1565	+/** The circular difference between two headings, 0 to 32. */
1566	+export function headingDifference(a: number, b: number): number {
1567	+  const difference = normalizeHeading(a - b);
1568	+  return Math.min(difference, HEADING_COUNT - difference);
1569	+}
1570	+
1571	+/**
1572	+ * Whether `to` lies within ±`cone` headings of `heading` seen from `from`. Distance 0 is inside every cone:
1573	+ * overlapping ships do not block each other.
1574	+ */
1575	+export function withinCone(from: EncounterPoint, to: EncounterPoint, heading: number, cone: number): boolean {
1576	+  const toward = bearing(from, to);
1577	+  return toward === null || headingDifference(toward, heading) <= cone;
1578	+}
