1580	+/** A tile, by its column and row. */
1581	+export interface TileCell {
1582	+  readonly tileX: number;
1583	+  readonly tileY: number;
1584	+}
1585	+
1586	+/**
1587	+ * Every tile the segment between the centres of two tiles touches: a supercover line. Where it passes exactly
1588	+ * through a tile corner, both tiles beside the corner count. The set is the same in either direction; the list runs
1589	+ * from `from` to `to`.
1590	+ */
1591	+export function supercover(from: TileCell, to: TileCell): TileCell[] {
1592	+  const nx = Math.abs(to.tileX - from.tileX);
1593	+  const ny = Math.abs(to.tileY - from.tileY);
1594	+  const sx = to.tileX > from.tileX ? 1 : -1;
1595	+  const sy = to.tileY > from.tileY ? 1 : -1;
1596	+  let x = from.tileX;
1597	+  let y = from.tileY;
1598	+  const cells: TileCell[] = [{ tileX: x, tileY: y }];
1599	+  let ix = 0;
1600	+  let iy = 0;
1601	+  while (ix < nx || iy < ny) {
1602	+    // Compares where the segment next crosses a vertical and a horizontal tile edge, in exact integers.
1603	+    const decision = (1 + 2 * ix) * ny - (1 + 2 * iy) * nx;
1604	+    if (decision === 0) {
1605	+      cells.push({ tileX: x + sx, tileY: y }, { tileX: x, tileY: y + sy });
1606	+      x += sx;
1607	+      y += sy;
1608	+      ix++;
1609	+      iy++;
1610	+    } else if (decision < 0) {
1611	+      x += sx;
1612	+      ix++;
1613	+    } else {
1614	+      y += sy;
1615	+      iy++;
1616	+    }
1617	+    cells.push({ tileX: x, tileY: y });
1618	+  }
1619	+  return cells;
